// Accepts WAHA (waha.devlike.pro) and Meta WhatsApp Cloud API webhooks.
// Extracts sender name, message text and a normalized Israeli phone number.
const req = $input.first().json;
const body = req.body ?? req;

let raw = '';
let text = '';
let name = '';

if (body.payload) {
  // WAHA payload: { event: 'message', payload: { from, body, fromMe, _data } }
  const p = body.payload;
  if (p.fromMe) return []; // ignore messages sent by us
  raw = p.from ?? '';
  if (String(raw).endsWith('@g.us')) return []; // ignore group chats
  text = p.body ?? '';
  name = p._data?.notifyName ?? p.notifyName ?? '';
} else if (body.entry) {
  // WhatsApp Cloud API payload: entry[0].changes[0].value
  const value = body.entry?.[0]?.changes?.[0]?.value ?? {};
  const msg = value.messages?.[0];
  if (!msg) return []; // ignore delivery/status callbacks
  raw = msg.from ?? '';
  text = msg.text?.body ?? '';
  name = value.contacts?.[0]?.profile?.name ?? '';
} else {
  return []; // unknown payload shape
}

if (!raw) return [];

// Normalize to Israeli E.164 (+972...). Adjust the prefix for other countries.
let digits = String(raw).replace(/@.*$/, '').replace(/\D/g, '');
if (digits.startsWith('0')) digits = '972' + digits.slice(1);
if (!digits.startsWith('972')) digits = '972' + digits;

return [{
  json: {
    name: name || 'New WhatsApp lead',
    phone: '+' + digits,
    chatId: digits + '@c.us',
    message: text,
    receivedAt: $now.toISO(),
    source: 'WhatsApp',
  },
}];
